# Run from the package root:  Rscript data-raw/qa/60_no_end_point_section.R
# Writes the section "Tornadoes with no usable end point" of data-raw/known_issues.md (between <!-- no-end-point:start --> and <!-- no-end-point:end -->) from the stored data.
# A tornado has no usable end point when SPC's end coordinates are missing, 0, or equal to the start. All numbers are computed here.
suppressMessages({library(sf); library(dplyr)}); source("data-raw/qa/helpers.R")
for (f in list.files("data", pattern = "\\.rda$", full.names = TRUE)) load(f)
tt <- st_drop_geometry(tornado_tracks); yr <- as.integer(substr(tt$tornado_id, 1, 4)); era <- ifelse(yr < 2007, "1996-2006", "2007 on"); p <- tt$track_type == "point"
rating <- ifelse(is.na(tt$magnitude), "unknown", paste0("EF", tt$magnitude)); f0 <- function(x) formatC(x, format = "d", big.mark = ","); pc <- function(x, d = 1) sprintf(paste0("%.", d, "f%%"), 100 * x); n <- nrow(tt)
md <- function(df) { df[] <- lapply(df, as.character); paste(c(paste0("| ", paste(names(df), collapse = " | "), " |"), paste0("|", paste(rep("---", ncol(df)), collapse = "|"), "|"), apply(df, 1, function(r) paste0("| ", paste(r, collapse = " | "), " |"))), collapse = "\n") }
by_rating <- do.call(rbind, lapply(c("EF0", "EF1", "EF2", "EF3", "EF4", "EF5", "unknown"), function(r) data.frame(Rating = r, `All tornadoes` = f0(sum(rating == r)), `No usable end point` = f0(sum(rating == r & p)), `Share of this rating` = pc(mean(p[rating == r])), `Share of all such tornadoes` = pc(sum(rating == r & p) / sum(p)), check.names = FALSE)))
lb <- cut(tt$len_mi[p], c(-Inf, 0, 0.5, 1, 5, Inf), labels = c("0 (reported length is zero)", "above 0 and under 0.5 mile", "0.5 to under 1 mile", "1 to under 5 miles", "5 miles or more"), right = TRUE)
lb <- cut(tt$len_mi[p], c(-Inf, 0, 0.5 - 1e-9, 1 - 1e-9, 5 - 1e-9, Inf), labels = c("0 (reported length is zero)", "above 0 and under 0.5 mile", "0.5 to under 1 mile", "1 to under 5 miles", "5 miles or more"))
len_tab <- data.frame(`Reported length` = names(table(lb)), Tornadoes = f0(as.integer(table(lb))), Share = pc(as.integer(table(lb)) / sum(p)), check.names = FALSE)
q <- function(x) quantile(x, c(.5, .9), names = FALSE); L <- tt$len_mi[p]; w_known <- tt$wid_yd[p & tt$wid_yd > 0 & !is.na(tt$wid_yd)]
yr_tab <- do.call(rbind, lapply(list(c(1996, 1996), c(1997, 2001), c(2002, 2006), c(2007, 2010), c(2011, 2015), c(2016, 2020), c(2021, 2025)), function(a) { k <- yr >= a[1] & yr <= a[2]; data.frame(Years = if (a[1] == a[2]) a[1] else paste0(a[1], "-", a[2]), Tornadoes = f0(sum(k)), `No usable end point` = f0(sum(k & p)), Share = pc(mean(p[k])), check.names = FALSE) }))
sh <- function(e, r) mean(p[era == e & (if (r == "EF0") rating == "EF0" else if (r == "EF1+") rating %in% paste0("EF", 1:5) else rating == "unknown")])
cross <- data.frame(Era = c("1996-2006", "2007 on"), EF0 = pc(c(sh("1996-2006", "EF0"), sh("2007 on", "EF0"))), `EF1 to EF5` = pc(c(sh("1996-2006", "EF1+"), sh("2007 on", "EF1+"))), Unknown = c("none", pc(sh("2007 on", "unknown"))), check.names = FALSE)
era_gap <- c(EF0 = sh("1996-2006", "EF0") - sh("2007 on", "EF0"), `EF1+` = sh("1996-2006", "EF1+") - sh("2007 on", "EF1+")); str_gap <- c(`1996-2006` = sh("1996-2006", "EF0") - sh("1996-2006", "EF1+"), `2007 on` = sh("2007 on", "EF0") - sh("2007 on", "EF1+"))
era_more <- all(era_gap > str_gap[c(1, 2)]) ; k <- era == "1996-2006"
txt <- c("<!-- no-end-point:start -->", "## Tornadoes with no usable end point", "",
 paste0("A tornado has no usable end point when SPC's end coordinates are missing, equal to 0, or equal to the start coordinates. ", f0(sum(p)), " of the ", f0(n), " tornadoes (", pc(mean(p)), ") are of this kind (", f0(sum(p & tt$elon == tt$slon & tt$elat == tt$slat, na.rm = TRUE)), " have an end equal to the start, ", f0(sum(p & !(tt$elon == tt$slon & tt$elat == tt$slat), na.rm = TRUE)), " an end of 0 or missing). ", f0(sum(p & k)), " of them (", pc(sum(p & k) / sum(p)), ") are from 1996 to 2006 and ", f0(sum(p & !k)), " (", pc(sum(p & !k) / sum(p)), ") from 2007 on. The package draws each as a POINT at the start (`track_type = \"point\"`), keeps SPC's raw coordinates, length and width, and models no path shape: the `modeled_*` columns are `NA` (the real path has an unknown direction and may extend up to the reported length from the start). In `tornado_exposure` such a tornado has one row, the ZCTA that contains the start point; ", f0(sum(p & tt$tornado_id %in% setdiff(tornado_tracks$tornado_id, tornado_exposure$tornado_id))), " start points lie in no ZCTA and have no row."),
 "",
 "**By rating.**", "", md(by_rating), "",
 paste0("**Reported length** (SPC's `len`, in miles; median ", sprintf("%.2f", q(L)[1]), ", 90th percentile ", sprintf("%.2f", q(L)[2]), ", longest ", sprintf("%.1f", max(L)), "; ", f0(sum(L > 0)), " of ", f0(sum(p)), " (", pc(mean(L > 0)), ") have a length above 0):"), "", md(len_tab), "",
 paste0("**Injuries and deaths.** These tornadoes account for ", f0(sum(tt$total_injury[p])), " of ", f0(sum(tt$total_injury)), " injuries (", pc(sum(tt$total_injury[p]) / sum(tt$total_injury)), ") and ", f0(sum(tt$total_fatality[p])), " of ", f0(sum(tt$total_fatality)), " deaths (", pc(sum(tt$total_fatality[p]) / sum(tt$total_fatality)), "); ", f0(sum(p & tt$total_fatality > 0)), " of them have at least one death."), "",
 paste0("**Reported width.** SPC's width (`wid`, yards) is 0 or missing for ", f0(sum(tt$wid_yd[p] == 0 | is.na(tt$wid_yd[p]))), " of these tornadoes (", pc(mean(tt$wid_yd[p] == 0 | is.na(tt$wid_yd[p]))), "); for the others the median is ", f0(median(w_known)), " yards and the 90th percentile ", f0(q(w_known)[2]), " yards. A width is never replaced.", NULL), "",
 "**By year.**", "", md(yr_tab), "", "**By era and rating** (share of tornadoes with no usable end point):", "", md(cross), "",
 paste0("**Plain reading.** ", pc(mean(rating[p] == "EF0")), " of these tornadoes are EF0 and the median reported length is ", sprintf("%.2f", q(L)[1]), " mile, but SPC gives a length above 0 for ", pc(mean(L > 0)), " of them, ", f0(sum(L >= 1)), " are 1 mile or longer, ", f0(sum(L >= 5)), " are 5 miles or longer, and the longest is ", sprintf("%.1f", max(L)), " miles, so they are not all brief touchdowns: the real path may extend up to the reported length from the start point in an unknown direction. ",
   if (era_more) paste0("The share follows the era more than the strength: between 1996-2006 and 2007 on it falls by ", sprintf("%.0f", 100 * era_gap[["EF0"]]), " percentage points among EF0 tornadoes and ", sprintf("%.0f", 100 * era_gap[["EF1+"]]), " points among EF1 to EF5, while within 1996-2006 it differs by ", sprintf("%.0f", 100 * str_gap[["1996-2006"]]), " points between EF0 and EF1 to EF5 (", sprintf("%.0f", 100 * str_gap[["2007 on"]]), " points from 2007 on). Coordinates before 2007 are rounded to 0.01 degrees, so start and end points of short tornadoes often coincide.") else "The share depends on both the era and the strength (see the table above)."),
 "<!-- no-end-point:end -->")
kl <- readLines("data-raw/known_issues.md"); a <- grep("<!-- no-end-point:start -->", kl, fixed = TRUE); b <- grep("<!-- no-end-point:end -->", kl, fixed = TRUE)
kl <- if (length(a) && length(b)) c(kl[seq_len(a - 1)], txt, kl[-seq_len(b)]) else append(kl, c(txt, ""), after = grep("^## Point tracks", kl)[1] - 1)
writeLines(kl, "data-raw/known_issues.md"); cat(txt, sep = "\n")
